/* Feste Übersetzung der Lerninhalte (fa), maschinell erstellt, nicht von Muttersprachlern geprüft. Code bleibt unverändert. */
(function(r){"use strict";const f=r.SDAkademieFest=r.SDAkademieFest||{};(f["fa"]=f["fa"]||{})["code"]={"Was ist eine Webseite?":"ویب‌سایت چیست؟","Du kannst die drei Bausteine einer Webseite unterscheiden.":"شما می‌توانید سه بخش سازندهٔ یک ویب‌سایت را از هم جدا کنید.","Drei Aufgaben einer Webseite":"سه کار یک ویب‌سایت","Wenn du eine Bäckerei besuchst, siehst du Produkte, Schilder und vielleicht eine Klingel. Bei einer Webseite übernimmt HTML die Inhalte. CSS gestaltet Farben und Abstände. JavaScript sorgt für Reaktionen auf einen Klick.":"وقتی به یک نانوایی می‌روید، محصولات، تابلوها و شاید یک زنگ را می‌بینید. در یک ویب‌سایت HTML محتوا را به عهده دارد. CSS رنگ‌ها و فاصله‌ها را طراحی می‌کند. JavaScript واکنش به یک کلیک را فراهم می‌کند.","Zeile 1 zeigt den Namen als große Überschrift. Zeile 2 schreibt eine Nachricht darunter.":"خط 1 نام را به شکل یک عنوان بزرگ نشان می‌دهد. خط 2 یک پیام زیر آن می‌نویسد.","HTML beschreibt den Inhalt":"HTML محتوا را توصیف می‌کند","HTML bedeutet Hypertext Markup Language. Ein Element beginnt oft mit einem Start-Tag und endet mit einem End-Tag. Der Text dazwischen wird angezeigt. Die spitzen Klammern gehören zur Schreibweise.":"HTML یعنی Hypertext Markup Language. یک عنصر اغلب با یک تگ شروع آغاز و با یک تگ پایان تمام می‌شود. متن بین آن‌ها نشان داده می‌شود. قوس‌های زاویه‌دار بخشی از شکل نوشتن هستند.","Das p am Anfang startet einen Absatz. Der Text ist sichtbar. Das /p beendet ihn.":"p در آغاز یک پاراگراف را شروع می‌کند. متن قابل دید است. ‎/p آن را تمام می‌کند.","CSS verändert die Gestaltung":"CSS طراحی را تغییر می‌دهد","Ein Geschäft kann seine Wände streichen, ohne seine Produkte zu verändern. Genau so ändert CSS das Aussehen von HTML. Eine Regel nennt zuerst das Element. Zwischen geschweiften Klammern steht die Gestaltung.":"یک دکان می‌تواند دیوارهایش را رنگ کند، بدون اینکه محصولاتش را تغییر دهد. CSS هم دقیقاً همین‌طور ظاهر HTML را تغییر می‌دهد. یک قاعده اول عنصر را نام می‌برد. بین قوس‌های گُل‌دار طراحی نوشته می‌شود.","Zeile 1 wählt alle h1-Überschriften. Zeile 2 setzt ihre Textfarbe. Zeile 3 schließt die Regel.":"خط 1 همهٔ عنوان‌های h1 را انتخاب می‌کند. خط 2 رنگ متن آن‌ها را می‌گذارد. خط 3 قاعده را می‌بندد.","JavaScript macht die Seite lebendig":"JavaScript صفحه را زنده می‌کند","Eine Türklingel reagiert erst, wenn jemand drückt. Ein JavaScript-Programm kann ebenso auf eine Aktion warten. Der Browser führt diese Befehle aus. Später baust du einen eigenen Knopf.":"زنگ دروازه فقط وقتی واکنش نشان می‌دهد که کسی فشارش دهد. یک برنامهٔ JavaScript هم می‌تواند همین‌طور منتظر یک کار بماند. براوزر این دستورها را اجرا می‌کند. بعداً یک دکمهٔ خودتان را می‌سازید.","querySelector sucht die erste h1-Überschrift. textContent ersetzt ihren Text. Das Semikolon beendet den Befehl.":"querySelector اولین عنوان h1 را جستجو می‌کند. textContent متن آن را عوض می‌کند. نقطه‌کامه دستور را تمام می‌کند.","HTML und CSS verwechselt":"اشتباه گرفتن HTML و CSS","Eine Farbe gehört in CSS, nicht in den Text eines h1-Tags.":"یک رنگ جایش در CSS است، نه در متن یک تگ h1.","Schließendes Tag vergessen":"فراموش کردن تگ پایان","Wenn der Absatz falsch dargestellt wird, prüfe das Ende </p>.":"اگر پاراگراف اشتباه نشان داده شود، پایان </p> را بررسی کنید.","JavaScript als sichtbaren Text geschrieben":"JavaScript به شکل متن قابل دید نوشته شد","Ein Befehl gehört in die JavaScript-Datei und nicht als Satz in den Absatz.":"یک دستور جایش در فایل JavaScript است، نه به شکل جمله در پاراگراف.","Schreibe eine eigene Überschrift und einen Begrüßungstext.":"یک عنوان و یک متن خوش‌آمد خودتان بنویسید.","Prüfe den Beispielcode Zeile für Zeile. Achte auf die genaue Schreibweise.":"کد مثال را خط به خط بررسی کنید. به املای دقیق توجه کنید.","Es gibt eine Überschrift.":"یک عنوان وجود دارد.","Die Startüberschrift wurde geändert.":"عنوان شروع تغییر کرده است.","Es gibt einen Absatz.":"یک پاراگراف وجود دارد.","Welche Sprache beschreibt eine Überschrift?":"کدام زبان یک عنوان را توصیف می‌کند؟","HTML beschreibt den sichtbaren Inhalt.":"HTML محتوای قابل دید را توصیف می‌کند.","CSS bestimmt vor allem das Aussehen.":"CSS بیشتر ظاهر را تعیین می‌کند.","JavaScript steuert Reaktionen.":"JavaScript واکنش‌ها را کنترول می‌کند.","Was bewirkt color: blue in einer CSS-Regel?":"color: blue در یک قاعدهٔ CSS چه کار می‌کند؟","Es färbt den Text blau.":"متن را آبی می‌کند.","Es öffnet eine neue Seite.":"یک صفحهٔ تازه باز می‌کند.","Es erzeugt einen Knopf.":"یک دکمه می‌سازد.","Die Eigenschaft color setzt die Schriftfarbe.":"ویژگی color رنگ متن را می‌گذارد.","Ein Link braucht HTML und eine Adresse.":"یک لینک به HTML و یک آدرس نیاز دارد.","Ein Knopf wird mit HTML angelegt.":"یک دکمه با HTML ساخته می‌شود.","Wann hilft JavaScript?":"JavaScript چه وقت کمک می‌کند؟","Beim Schließen eines HTML-Tags.":"هنگام بستن یک تگ HTML.","Beim Speichern eines Bildes.":"هنگام ذخیرهٔ یک عکس.","Wenn eine Seite auf einen Klick reagieren soll.":"وقتی یک صفحه باید به یک کلیک واکنش نشان دهد.","JavaScript verarbeitet Ereignisse wie Klicks.":"JavaScript رویدادهایی مثل کلیک را پردازش می‌کند.","Das End-Tag ist Teil von HTML.":"تگ پایان بخشی از HTML است.","Ein Bild ist eine Datei oder Datenquelle.":"یک عکس یک فایل یا منبع داده است.","HTML bedeutet Sprache für Webseiten-Inhalte. Ein h1-Element ist eine große Überschrift.":"HTML یعنی زبانی برای محتوای ویب‌سایت. یک عنصر h1 یک عنوان بزرگ است.","Im Browser siehst du das Ergebnis. Der Browser ist das Programm, mit dem du Webseiten öffnest.":"در براوزر نتیجه را می‌بینید. براوزر برنامه‌ای است که با آن ویب‌سایت‌ها را باز می‌کنید.","HTML zeigt Inhalte, CSS gestaltet sie und JavaScript reagiert auf Aktionen.":"HTML محتوا را نشان می‌دهد، CSS آن را طراحی می‌کند و JavaScript به کارها واکنش نشان می‌دهد.","Deine erste HTML-Datei":"اولین فایل HTML شما","Du kannst das Grundgerüst einer HTML-Datei schreiben.":"شما می‌توانید اسکلت پایهٔ یک فایل HTML را بنویسید.","Eine Datei ist ein vollständiges Dokument":"یک فایل یک سند کامل است","Ein Brief hat einen Umschlag, eine Anrede und einen Inhalt. Eine HTML-Datei besitzt ebenfalls feste Bereiche. Der Browser liest diese Struktur von oben nach unten. Der Dateiname ist oft index.html.":"یک نامه یک پاکت، یک خطاب و یک محتوا دارد. یک فایل HTML هم بخش‌های ثابت دارد. براوزر این ساختار را از بالا به پایین می‌خواند. نام فایل اغلب index.html است.","Die erste Zeile nennt den Dokumenttyp. Die zweite öffnet das HTML-Dokument und legt Deutsch als Sprache fest. Die dritte schließt es.":"خط اول نوع سند را نام می‌برد. خط دوم سند HTML را باز می‌کند و آلمانی را به عنوان زبان تعیین می‌کند. خط سوم آن را می‌بندد.","Informationen gehören in den head":"معلومات در head جا دارند","Auf einem Briefumschlag steht etwas anderes als im Brieftext. Im head stehen Informationen über die Seite. Der title ist der Name des Browser-Tabs. Besucher sehen ihn nicht als Überschrift im Inhalt.":"روی پاکت نامه چیز دیگری نوشته می‌شود تا در متن نامه. در head معلوماتی دربارهٔ صفحه قرار دارد. title نام تب براوزر است. بازدیدکنندگان آن را به شکل عنوان در محتوا نمی‌بینند.","head öffnet den Informationsbereich. title setzt den Tab-Namen. Das letzte Tag beendet den Bereich.":"head بخش معلومات را باز می‌کند. title نام تب را می‌گذارد. تگ آخر بخش را تمام می‌کند.","Der body enthält die sichtbare Seite":"body صفحهٔ قابل دید را در بر دارد","Alles, was die Person auf der Webseite lesen soll, kommt in den body. Dazu zählen Überschriften, Texte und später Bilder. Der Browser stellt diese Elemente im Fenster dar. Ein title im head ersetzt keine sichtbare Überschrift.":"هر چیزی که شخص باید در ویب‌سایت بخواند در body می‌آید. عنوان‌ها، متن‌ها و بعداً عکس‌ها جزو آن هستند. براوزر این عنصرها را در پنجره نشان می‌دهد. یک title در head جای یک عنوان قابل دید را نمی‌گیرد.","Die erste Zeile beginnt den sichtbaren Bereich. Die zweite erzeugt eine Überschrift. Die dritte beendet den Bereich.":"خط اول بخش قابل دید را شروع می‌کند. خط دوم یک عنوان می‌سازد. خط سوم بخش را تمام می‌کند.","Zeichenkodierung schützt Umlaute":"کدگذاری حروف از حروف خاص محافظت می‌کند","Wörter wie Käse und Grüße sollen richtig erscheinen. Deshalb gibst du im head die Kodierung UTF-8 an. Sie hilft dem Browser beim Lesen vieler Zeichen. Schreibe die Angabe möglichst weit oben.":"کلمه‌هایی مثل Käse و Grüße باید درست نشان داده شوند. به همین دلیل در head کدگذاری UTF-8 را می‌نویسید. این به براوزر در خواندن حروف زیاد کمک می‌کند. این معلومات را تا حد ممکن بالا بنویسید.","meta gibt eine Information an den Browser weiter. charset benennt die Zeichenkodierung. Dieses Element braucht kein End-Tag.":"meta یک معلومات را به براوزر می‌دهد. charset کدگذاری حروف را نام می‌برد. این عنصر به تگ پایان نیاز ندارد.","body im head verschachtelt":"body داخل head قرار گرفت","Der sichtbare Bereich gehört nach dem schließenden </head>.":"بخش قابل دید بعد از </head> بسته جا دارد.","title mit h1 verwechselt":"اشتباه گرفتن title با h1","Der Tab-Name steht in title; die große sichtbare Überschrift in h1.":"نام تب در title و عنوان بزرگ قابل دید در h1 است.","DOCTYPE weggelassen":"حذف کردن DOCTYPE","Beginne die komplette Datei mit <!doctype html>, damit der Browser den richtigen Modus nutzt.":"تمام فایل را با <!doctype html> شروع کنید تا براوزر حالت درست را به کار ببرد.","Erstelle eine HTML-Datei mit doctype, html, head, title und body.":"یک فایل HTML با doctype، html، head، title و body بسازید.","Die Datei beginnt mit <!doctype html>.":"فایل با <!doctype html> شروع می‌شود.","Es gibt einen head-Bereich.":"یک بخش head وجود دارد.","Der Seitentitel ist gesetzt.":"عنوان صفحه گذاشته شده است.","Es gibt einen body-Bereich.":"یک بخش body وجود دارد.","Wo steht der sichtbare Inhalt?":"محتوای قابل دید کجاست؟","Im title":"در title","Im head":"در head","Im body":"در body","body enthält sichtbare Elemente.":"body عنصرهای قابل دید را در بر دارد.","title benennt den Tab.":"title تب را نام‌گذاری می‌کند.","head enthält Metadaten.":"head فراداده‌ها را در بر دارد.","Welche Zeile gehört an den Anfang einer HTML-Datei?":"کدام خط در آغاز یک فایل HTML جا دارد؟","Damit erkennt der Browser den Dokumenttyp.":"با این کار براوزر نوع سند را تشخیص می‌دهد.","Ein Absatz gehört in den body.":"یک پاراگراف در body جا دارد.","Der Titel gehört in den head.":"عنوان در head جا دارد.","Wofür steht <meta charset=\"utf-8\">?":"<meta charset=\"utf-8\"> برای چیست؟","Für die Hintergrundfarbe.":"برای رنگ پس‌زمینه.","Für die Zeichenkodierung.":"برای کدگذاری حروف.","Für einen anklickbaren Link.":"برای یک لینک قابل کلیک.","UTF-8 sorgt für korrekt gelesene Zeichen.":"UTF-8 باعث می‌شود حروف درست خوانده شوند.","Farben werden mit CSS festgelegt.":"رنگ‌ها با CSS تعیین می‌شوند.","Links entstehen mit a und href.":"لینک‌ها با a و href ساخته می‌شوند.","<!doctype html> sagt dem Browser, dass die Datei HTML enthält.":"<!doctype html> به براوزر می‌گوید که فایل HTML دارد.","Im head stehen Informationen. Im body steht der sichtbare Inhalt.":"در head معلومات است. در body محتوای قابل دید است.","Ein vollständiges HTML-Dokument hat einen Dokumenttyp sowie Kopf- und Inhaltsbereich.":"یک سند کامل HTML یک نوع سند و همچنین بخش سر و بخش محتوا دارد.","Überschriften und Text":"عنوان‌ها و متن","Du kannst Texte mit Überschriften ordnen.":"شما می‌توانید متن‌ها را با عنوان‌ها مرتب کنید.","Die Hauptüberschrift nennt das Thema":"عنوان اصلی موضوع را نام می‌برد","Eine Zeitung hat oben einen großen Titel. Auf deiner Seite übernimmt h1 diese Aufgabe. Verwende eine klare Aussage statt eines ungenauen Wortes. Menschen erkennen dadurch sofort, worum es geht.":"یک روزنامه در بالا یک عنوان بزرگ دارد. در صفحهٔ شما h1 این کار را انجام می‌دهد. به جای یک کلمهٔ نامشخص یک جملهٔ روشن به کار ببرید. به این ترتیب مردم فوراً می‌فهمند که موضوع چیست.","h1 öffnet die Hauptüberschrift. Der Text nennt das Thema. Das End-Tag schließt die Überschrift.":"h1 عنوان اصلی را باز می‌کند. متن موضوع را نام می‌برد. تگ پایان عنوان را می‌بندد.","Unterüberschriften teilen den Inhalt":"عنوان‌های فرعی محتوا را تقسیم می‌کنند","In einem Kochbuch gibt es Kapitel für Frühstück und Abendessen. h2 kennzeichnet solche Abschnitte unter der Hauptüberschrift. Die Reihenfolge hilft beim Lesen. Überspringe Ebenen nicht nur wegen einer kleineren Schrift.":"در یک کتاب آشپزی فصل‌هایی برای صبحانه و شام هست. h2 چنین بخش‌هایی را زیر عنوان اصلی مشخص می‌کند. ترتیب به خواندن کمک می‌کند. سطح‌ها را فقط به خاطر یک فونت کوچک‌تر رد نکنید.","Die erste Zeile nennt das Gesamtthema. Die zweite Zeile beginnt einen Unterbereich.":"خط اول موضوع کلی را نام می‌برد. خط دوم یک بخش فرعی را شروع می‌کند.","Ein Absatz enthält zusammengehörige Sätze":"یک پاراگراف جمله‌های مربوط به هم را در بر دارد","Ein längerer Text braucht Pausen für die Augen. Das p-Element erstellt einen Absatz. Für einen neuen Gedanken beginnt ein neues p. Mehrere Leerzeichen im HTML ersetzen keine saubere Absatzstruktur.":"یک متن طولانی‌تر برای چشم‌ها به توقف نیاز دارد. عنصر p یک پاراگراف می‌سازد. برای یک فکر تازه یک p تازه شروع می‌شود. چند فاصله در HTML جای یک ساختار درست پاراگراف را نمی‌گیرد.","Die erste Zeile beschreibt Montag. Die zweite beginnt einen eigenen Absatz für Dienstag.":"خط اول دوشنبه را توصیف می‌کند. خط دوم یک پاراگراف جداگانه برای سه‌شنبه شروع می‌کند.","Die Struktur ist wichtiger als die Schriftgröße":"ساختار از اندازهٔ فونت مهم‌تر است","Eine Überschrift ist nicht nur großer Text. Browser und Hilfsprogramme erkennen die Bedeutung von h1 und h2. Für eine andere Schriftgröße verwendest du später CSS. So bleibt dein Dokument verständlich.":"یک عنوان فقط متن بزرگ نیست. براوزر و برنامه‌های کمکی معنای h1 و h2 را تشخیص می‌دهند. برای اندازهٔ فونت دیگر بعداً CSS را به کار می‌برید. به این ترتیب سند شما قابل فهم می‌ماند.","h2 wählt die Unterüberschriften. font-size ändert ihre Größe. Die Klammer beendet die CSS-Regel.":"h2 عنوان‌های فرعی را انتخاب می‌کند. font-size اندازهٔ آن‌ها را تغییر می‌دهد. قوس قاعدهٔ CSS را تمام می‌کند.","Alle Zeilen als h1 geschrieben":"همهٔ خط‌ها به شکل h1 نوشته شدند","Verwende eine Hauptüberschrift und ordne Unterthemen mit h2.":"یک عنوان اصلی به کار ببرید و موضوع‌های فرعی را با h2 مرتب کنید.","Absatz ohne p-Tag":"پاراگراف بدون تگ p","Text kann erscheinen, aber mit p wird seine Bedeutung klar.":"متن ممکن است نشان داده شود، اما با p معنای آن روشن می‌شود.","Überschrift nur mit Leerzeichen eingerückt":"عنوان فقط با فاصله تورفته شد","Nutze echte Überschriften-Elemente statt optischer Tricks.":"به جای ترفندهای ظاهری از عنصرهای واقعی عنوان استفاده کنید.","Schreibe eine eigene h1, eine h2 und zwei Absätze.":"یک h1، یک h2 و دو پاراگراف خودتان بنویسید.","Es gibt eine Unterüberschrift.":"یک عنوان فرعی وجود دارد.","Es gibt zwei Absätze.":"دو پاراگراف وجود دارد.","Welche Reihenfolge ist sinnvoll?":"کدام ترتیب معقول است؟","Die Hierarchie ist klar und gut lesbar.":"سلسله‌مراتب روشن و خوب خواناست.","Die Unterüberschrift sollte unter dem Haupttitel stehen.":"عنوان فرعی باید زیر عنوان اصلی باشد.","Absätze ersetzen keine Überschriften.":"پاراگراف‌ها جای عنوان‌ها را نمی‌گیرند.","Wofür verwendest du p?":"p را برای چه به کار می‌برید؟","Für einen Absatz.":"برای یک پاراگراف.","Für einen Browser-Tab.":"برای یک تب براوزر.","Für eine Bildquelle.":"برای منبع یک عکس.","p fasst einen Textabschnitt zusammen.":"p یک بخش متن را جمع می‌کند.","Der Tab-Titel steht in title.":"عنوان تب در title است.","Bilder verwenden src.":"عکس‌ها از src استفاده می‌کنند.","Wie machst du h2 kleiner, ohne seine Bedeutung zu ändern?":"h2 را چطور کوچک‌تر می‌کنید، بدون اینکه معنایش تغییر کند؟","Mit einem weiteren h1.":"با یک h1 دیگر.","Mit einem leeren Absatz.":"با یک پاراگراف خالی.","Mit CSS und font-size.":"با CSS و font-size.","CSS gestaltet die vorhandene Überschrift.":"CSS عنوان موجود را طراحی می‌کند.","Ein h1 verändert die Struktur.":"یک h1 ساختار را تغییر می‌دهد.","Ein leerer Absatz hilft nicht.":"یک پاراگراف خالی کمک نمی‌کند.","h1 ist die wichtigste Überschrift. h2 ist eine Unterüberschrift.":"h1 مهم‌ترین عنوان است. h2 یک عنوان فرعی است.","p bedeutet Absatz. Ein Absatz macht längere Texte lesbar.":"p یعنی پاراگراف. یک پاراگراف متن‌های طولانی‌تر را خوانا می‌کند.","Überschriften strukturieren eine Seite; Absätze erklären die Inhalte.":"عنوان‌ها یک صفحه را ساختار می‌دهند؛ پاراگراف‌ها محتوا را توضیح می‌دهند.","Listen":"لست‌ها","Du kannst Dinge in einer Liste sammeln.":"شما می‌توانید چیزها را در یک لست جمع کنید.","Listen helfen beim Einkaufen":"لست‌ها در خرید کمک می‌کنند","Drei Lebensmittel in einem langen Satz sind schwer zu überblicken. Eine Liste zeigt jeden Eintrag getrennt. Für eine Einkaufsliste spielt die Reihenfolge meist keine Rolle. Dafür gibt es ul.":"سه خوراکی در یک جملهٔ طولانی به سختی دیده می‌شوند. یک لست هر عنصر را جدا نشان می‌دهد. برای یک لست خرید ترتیب معمولاً اهمیتی ندارد. برای این کار ul وجود دارد.","ul beginnt die Liste. li fügt Reis als Punkt hinzu. Das letzte Tag beendet die Liste.":"ul لست را شروع می‌کند. li ‏Reis را به عنوان یک نقطه اضافه می‌کند. تگ آخر لست را تمام می‌کند.","Jeder Punkt braucht li":"هر نقطه به li نیاز دارد","Ein Zettel mit drei Zeilen enthält drei einzelne Dinge. In HTML bekommt jedes davon ein eigenes li-Element. Schreibe die Punkte innerhalb der Liste. Du kannst beliebig viele hinzufügen.":"یک کاغذ با سه خط سه چیز جداگانه دارد. در HTML هر کدام یک عنصر li جداگانه می‌گیرد. نقطه‌ها را داخل لست بنویسید. می‌توانید هر قدر بخواهید اضافه کنید.","Die erste Zeile ist ein Listenpunkt für Milch. Die zweite Zeile erzeugt einen weiteren für Äpfel.":"خط اول یک نقطهٔ لست برای Milch است. خط دوم یک نقطهٔ دیگر برای Äpfel می‌سازد.","Nummerierte Listen zeigen eine Reihenfolge":"لست‌های شماره‌دار یک ترتیب را نشان می‌دهند","Ein Rezept hat Schritte, die du nacheinander erledigst. Dafür ist ol passend. Der Browser nummeriert die li-Einträge automatisch. Du musst die Zahlen nicht selbst vor jeden Text schreiben.":"یک دستور پخت قدم‌هایی دارد که یکی پس از دیگری انجام می‌دهید. برای این کار ol مناسب است. براوزر عنصرهای li را خودکار شماره‌گذاری می‌کند. لازم نیست شماره‌ها را خودتان پیش از هر متن بنویسید.","ol beginnt eine nummerierte Liste. Die beiden li-Zeilen sind Schritt eins und zwei. Das End-Tag schließt die Folge.":"ol یک لست شماره‌دار را شروع می‌کند. دو خط li قدم یک و دو هستند. تگ پایان رشته را می‌بندد.","Listen dürfen weitere Inhalte enthalten":"لست‌ها می‌توانند محتوای دیگر هم داشته باشند","Du kannst eine kurze Überschrift vor deine Einkaufsliste setzen. So verstehen andere Menschen den Zweck der Punkte. Prüfe danach, ob jeder Eintrag einzeln erscheint. Eine Liste kann später auch Links enthalten.":"می‌توانید یک عنوان کوتاه پیش از لست خرید خود بگذارید. به این ترتیب دیگران هدف نقطه‌ها را می‌فهمند. بعد از آن بررسی کنید که آیا هر عنصر جدا نشان داده می‌شود. یک لست بعداً می‌تواند لینک هم داشته باشد.","Die erste Zeile benennt die Gruppe. ul beginnt die Liste. li zeigt Brot als einzelnen Punkt.":"خط اول گروه را نام می‌برد. ul لست را شروع می‌کند. li ‏Brot را به عنوان یک نقطهٔ جدا نشان می‌دهد.","li außerhalb von ul oder ol":"li بیرون از ul یا ol","Setze die Listenpunkte zwischen die öffnenden und schließenden Listentags.":"نقطه‌های لست را بین تگ‌های باز و بستهٔ لست بگذارید.","Alle Waren in einem einzigen li":"همهٔ جنس‌ها در یک li","Erstelle für jeden Artikel ein eigenes li-Element.":"برای هر جنس یک عنصر li جداگانه بسازید.","ul statt ol bei einer Anleitung":"ul به جای ol در یک دستورالعمل","Wenn die Reihenfolge wichtig ist, verwende eine nummerierte ol-Liste.":"اگر ترتیب مهم است، یک لست شماره‌دار ol به کار ببرید.","Erstelle eine Einkaufsliste mit mindestens drei Punkten.":"یک لست خرید با دست‌کم سه نقطه بسازید.","Es gibt eine Liste.":"یک لست وجود دارد.","Es gibt drei Listenpunkte.":"سه نقطهٔ لست وجود دارد.","Welcher Code zeigt Punkte ohne Nummern?":"کدام کد نقطه‌ها را بدون شماره نشان می‌دهد؟","ul zeigt eine Liste mit Punkten.":"ul یک لست با نقطه نشان می‌دهد.","ol nummeriert die Einträge.":"ol عنصرها را شماره‌گذاری می‌کند.","p erzeugt einen Absatz.":"p یک پاراگراف می‌سازد.","Was gehört in ein ul?":"چه چیزی در یک ul جا دارد؟","Ein oder mehrere li-Elemente.":"یک یا چند عنصر li.","Nur eine CSS-Regel.":"فقط یک قاعدهٔ CSS.","Ein title für den Browser-Tab.":"یک title برای تب براوزر.","li kennzeichnet die einzelnen Einträge.":"li عنصرهای جداگانه را مشخص می‌کند.","CSS gehört nicht als Listenpunkt hinein.":"CSS به عنوان نقطهٔ لست جا ندارد.","title steht im head.":"title در head است.","Welche Liste passt zu einer Kochanleitung?":"کدام لست با یک دستور آشپزی جور می‌آید؟","ul, weil die Reihenfolge egal ist.":"ul، چون ترتیب مهم نیست.","ol, weil Schritte aufeinander folgen.":"ol، چون قدم‌ها پشت سر هم می‌آیند.","p, weil jeder Schritt gleich aussieht.":"p، چون هر قدم یکسان به نظر می‌رسد.","ol nummeriert die Arbeitsschritte.":"ol قدم‌های کار را شماره‌گذاری می‌کند.","Bei einer Anleitung ist die Reihenfolge wichtig.":"در یک دستورالعمل ترتیب مهم است.","Absätze bieten keine automatische Nummerierung.":"پاراگراف‌ها شماره‌گذاری خودکار ندارند.","ul bedeutet Liste mit Punkten. Das ist eine Gruppe von Einträgen.":"ul یعنی لست با نقطه. این یک گروه از عنصرهاست.","li bedeutet Listenpunkt. Jeder Punkt hat ein eigenes Element.":"li یعنی نقطهٔ لست. هر نقطه یک عنصر جداگانه دارد.","Listeneinträge gehören in eine geordnete oder ungeordnete Liste.":"عنصرهای لست در یک لست مرتب یا نامرتب جا دارند.","Links":"لینک‌ها","Du kannst einen anklickbaren Link erstellen.":"شما می‌توانید یک لینک قابل کلیک بسازید.","Ein Link verbindet Webseiten":"یک لینک ویب‌سایت‌ها را به هم وصل می‌کند","Ein Wegweiser zeigt dir den Weg zu einem anderen Ort. Auf einer Webseite übernimmt ein Link diese Rolle. Ein a-Element macht Text anklickbar. Der Zielort steht in href.":"یک تابلوی راهنما راه یک جای دیگر را به شما نشان می‌دهد. در یک ویب‌سایت یک لینک این نقش را دارد. یک عنصر a متن را قابل کلیک می‌کند. مقصد در href نوشته می‌شود.","a beginnt den Link. href enthält die Internetadresse. Der Text zwischen den Tags ist anklickbar.":"a لینک را شروع می‌کند. href آدرس انترنتی را دارد. متن بین تگ‌ها قابل کلیک است.","Die Adresse muss vollständig sein":"آدرس باید کامل باشد","Eine Hausnummer ohne Straße reicht oft nicht aus. Auch bei externen Webseiten brauchst du eine vollständige Adresse. Sie beginnt meist mit https://. Prüfe Schreibfehler im Ziel.":"یک شمارهٔ خانه بدون نام سرک اغلب کافی نیست. برای ویب‌سایت‌های بیرونی هم به یک آدرس کامل نیاز دارید. معمولاً با https:// شروع می‌شود. اشتباه‌های تایپی در مقصد را بررسی کنید.","href zeigt auf die verschlüsselte Webadresse. Das Wort Lexikon beschreibt das Ziel. Das End-Tag beendet den Link.":"href به آدرس ویب رمزگذاری‌شده اشاره می‌کند. کلمهٔ Lexikon مقصد را توصیف می‌کند. تگ پایان لینک را تمام می‌کند.","Ein guter Linktext erklärt das Ziel":"یک متن لینک خوب مقصد را توضیح می‌دهد","Der Satz Klick hier sagt wenig über die nächste Seite. Besser ist ein Text wie Öffnungszeiten ansehen. Menschen mit Vorleseprogrammen verstehen dann das Ziel leichter. Halte den Linktext kurz und genau.":"جملهٔ «اینجا کلیک کنید» دربارهٔ صفحهٔ بعدی کم می‌گوید. متنی مثل «دیدن ساعات کار» بهتر است. در آن صورت کسانی که از برنامه‌های صفحه‌خوان استفاده می‌کنند مقصد را آسان‌تر می‌فهمند. متن لینک را کوتاه و دقیق نگه دارید.","Die Adresse führt zu einer Unterseite. Der sichtbare Text nennt den Inhalt dieser Seite.":"آدرس به یک صفحهٔ فرعی می‌برد. متن قابل دید محتوای این صفحه را نام می‌برد.","Links innerhalb deiner Seite":"لینک‌ها داخل صفحهٔ شما","Du kannst auch zu einer anderen Datei deines Projekts verlinken. Dafür reicht oft ein relativer Pfad. Relativ bedeutet: Der Weg beginnt am Ort deiner aktuellen Datei. Später kannst du mehrere Unterseiten verbinden.":"می‌توانید به یک فایل دیگر پروژهٔ خود هم لینک بدهید. برای این کار اغلب یک مسیر نسبی کافی است. نسبی یعنی: راه از جای فایل فعلی شما شروع می‌شود. بعداً می‌توانید چند صفحهٔ فرعی را به هم وصل کنید.","kontakt.html ist eine Datei im gleichen Ordner. Der Text Kontakt wird als Link angezeigt.":"kontakt.html یک فایل در همان پوشه است. متن Kontakt به شکل لینک نشان داده می‌شود.","href vergessen":"فراموش کردن href","Ein a-Element ohne Ziel sieht eventuell wie Text aus und führt nirgendwohin.":"یک عنصر a بدون مقصد ممکن است مثل متن به نظر برسد و به هیچ جا نبرد.","https falsch geschrieben":"https اشتباه نوشته شد","Prüfe den Anfang der Adresse und entferne Leerzeichen.":"آغاز آدرس را بررسی کنید و فاصله‌ها را پاک کنید.","Linktext ist nur hier":"متن لینک فقط «اینجا» است","Beschreibe lieber die Zielseite, damit der Link auch allein verständlich ist.":"بهتر است صفحهٔ مقصد را توصیف کنید تا لینک به تنهایی هم قابل فهم باشد.","Füge einen Link mit https-Adresse und lesbarem Text hinzu.":"یک لینک با آدرس https و متن خوانا اضافه کنید.","Es gibt einen Link.":"یک لینک وجود دارد.","Der Link hat eine https-Adresse.":"لینک یک آدرس https دارد.","Was enthält href?":"href چه چیزی را در بر دارد؟","Die Schriftfarbe.":"رنگ متن.","Die Zieladresse.":"آدرس مقصد.","Die Bildbeschreibung.":"توضیح عکس.","href legt das Ziel eines Links fest.":"href مقصد یک لینک را تعیین می‌کند.","Die Farbe gehört zu CSS.":"رنگ جزو CSS است.","alt beschreibt Bilder.":"alt عکس‌ها را توصیف می‌کند.","Welcher Link ist vollständig?":"کدام لینک کامل است؟","Der Link hat eine Adresse und einen sichtbaren Text.":"لینک یک آدرس و یک متن قابل دید دارد.","Ohne href fehlt das Ziel.":"بدون href مقصد کم است.","p ist ein Absatz, kein Linkelement.":"p یک پاراگراف است، نه عنصر لینک.","Welcher Linktext ist hilfreicher?":"کدام متن لینک مفیدتر است؟","Hier klicken":"اینجا کلیک کنید","Weiter":"بعدی","Fahrplan herunterladen":"دانلود جدول حرکت","Der Text beschreibt die Aktion konkret.":"این متن کار را مشخص توصیف می‌کند.","Der Text verrät das Ziel nicht.":"این متن مقصد را نشان نمی‌دهد.","Weiter ist ohne Kontext unklar.":"«بعدی» بدون زمینه نامشخص است.","a steht für Anker. Damit wird Text anklickbar.":"a مخفف Anker (لنگر) است. با آن متن قابل کلیک می‌شود.","href enthält die Zieladresse. Für externe Seiten nutzt du https.":"href آدرس مقصد را دارد. برای صفحه‌های بیرونی https را به کار می‌برید.","Ein Link benötigt ein sinnvolles Ziel im href-Attribut.":"یک لینک به یک مقصد معقول در صفت href نیاز دارد.","Bilder":"عکس‌ها","Du kannst ein Bild mit einem Alternativtext einfügen.":"شما می‌توانید یک عکس را با یک متن جایگزین اضافه کنید.","Bilder ergänzen einen Text":"عکس‌ها یک متن را کامل می‌کنند","Ein Foto auf einer Speisekarte hilft bei der Auswahl. Auf Webseiten setzt du Bilder mit img ein. Das Element benötigt eine Bildquelle. Diese steht in src.":"یک عکس روی یک منوی غذا به انتخاب کمک می‌کند. در ویب‌سایت‌ها عکس‌ها را با img می‌گذارید. این عنصر به یک منبع عکس نیاز دارد. این منبع در src نوشته می‌شود.","img fügt ein Bild ein. src nennt die Datei. alt beschreibt den sichtbaren Inhalt.":"img یک عکس اضافه می‌کند. src فایل را نام می‌برد. alt محتوای قابل دید را توصیف می‌کند.","Dateipfade müssen stimmen":"مسیرهای فایل باید درست باشند","Wenn ein Bild nicht erscheint, liegt es oft am Dateinamen. Groß- und Kleinschreibung können wichtig sein. Ein relativer Pfad zeigt auf einen Ort im Projekt. Achte auf Ordner und Endung.":"اگر یک عکس نشان داده نشود، اغلب به خاطر نام فایل است. حروف بزرگ و کوچک ممکن است مهم باشند. یک مسیر نسبی به جایی در پروژه اشاره می‌کند. به پوشه و پسوند توجه کنید.","bilder ist der Unterordner. apfel.png ist die Datei darin. alt nennt das Motiv.":"bilder پوشهٔ فرعی است. apfel.png فایل داخل آن است. alt موضوع را نام می‌برد.","Alternativtext macht Bilder zugänglich":"متن جایگزین عکس‌ها را دسترس‌پذیر می‌کند","Nicht alle Menschen können ein Bild sehen. Manche nutzen ein Vorleseprogramm. Der alt-Text erklärt dann, was das Bild zeigt. Bei wichtigen Bildern sollte er kurz und genau sein.":"همهٔ مردم نمی‌توانند یک عکس را ببینند. بعضی‌ها از یک برنامهٔ صفحه‌خوان استفاده می‌کنند. در آن صورت متن alt توضیح می‌دهد که عکس چه نشان می‌دهد. برای عکس‌های مهم باید کوتاه و دقیق باشد.","src verweist auf die Grafik. alt beschreibt die wichtige Information ohne unnötige Wörter.":"src به گرافیک اشاره می‌کند. alt معلومات مهم را بدون کلمه‌های غیرضروری توصیف می‌کند.","Eine Grafik kann direkt im Code stehen":"یک گرافیک می‌تواند مستقیم در کد باشد","Für diese Übung verwenden wir eine kleine SVG-Grafik. SVG bedeutet skalierbare Vektorgrafik. Sie bleibt beim Vergrößern scharf. Eine data:-Adresse kann die Bilddaten direkt enthalten.":"برای این تمرین از یک گرافیک کوچک SVG استفاده می‌کنیم. SVG یعنی گرافیک برداری مقیاس‌پذیر. هنگام بزرگ کردن واضح می‌ماند. یک آدرس data: می‌تواند داده‌های عکس را مستقیم در بر داشته باشد.","Der Anfang data:image/svg+xml kennzeichnet die eingebettete Grafik. alt bleibt auch bei solchen Bildern notwendig.":"آغاز data:image/svg+xml گرافیک جاسازی‌شده را مشخص می‌کند. alt برای چنین عکس‌هایی هم لازم می‌ماند.","Bilddatei am falschen Ort":"فایل عکس در جای اشتباه","Wenn nur ein leeres Symbol erscheint, prüfe den Pfad in src.":"اگر فقط یک نشانهٔ خالی نشان داده شود، مسیر در src را بررسی کنید.","alt-Text fehlt":"متن alt کم است","Ergänze eine kurze Beschreibung des Motivs für Vorleseprogramme.":"یک توضیح کوتاه از موضوع برای برنامه‌های صفحه‌خوان اضافه کنید.","Dateiendung verwechselt":"اشتباه گرفتن پسوند فایل","Eine Datei namens foto.png lässt sich nicht mit foto.jpg laden.":"فایلی به نام foto.png با foto.jpg بارگیری نمی‌شود.","Füge ein Bild mit einem passenden alt-Text ein.":"یک عکس با یک متن alt مناسب اضافه کنید.","Es gibt ein Bild.":"یک عکس وجود دارد.","Das Bild hat einen beschreibenden alt-Text.":"عکس یک متن alt توصیفی دارد.","Das Bild hat eine Bildquelle.":"عکس یک منبع عکس دارد.","Wofür ist alt wichtig?":"alt برای چه مهم است؟","Für die Textfarbe.":"برای رنگ متن.","Für die Größe des Bildschirms.":"برای اندازهٔ صفحهٔ نمایش.","Für eine verständliche Bildbeschreibung.":"برای یک توضیح قابل فهم از عکس.","Vorleseprogramme können den Text ausgeben.":"برنامه‌های صفحه‌خوان می‌توانند این متن را بخوانند.","Textfarben setzt CSS.":"رنگ متن را CSS می‌گذارد.","Die Bildschirmgröße ist unabhängig von alt.":"اندازهٔ صفحه به alt ربطی ندارد.","Welches Attribut nennt die Bilddatei?":"کدام صفت فایل عکس را نام می‌برد؟","src enthält die Bildquelle.":"src منبع عکس را در بر دارد.","href wird häufig für Links verwendet.":"href اغلب برای لینک‌ها به کار می‌رود.","class benennt eine Gruppe von Elementen.":"class یک گروه از عنصرها را نام‌گذاری می‌کند.","Warum erscheint bilder/katze.png möglicherweise nicht?":"چرا bilder/katze.png شاید نشان داده نشود؟","Weil alt zu lang ist.":"چون alt خیلی طولانی است.","Weil der Ordner oder Dateiname nicht stimmt.":"چون پوشه یا نام فایل درست نیست.","Weil img immer ein End-Tag braucht.":"چون img همیشه به تگ پایان نیاز دارد.","Ein falscher Pfad führt zu einem fehlenden Bild.":"یک مسیر اشتباه به یک عکس ناموجود می‌انجامد.","Ein alt-Text verhindert das Laden nicht.":"یک متن alt جلوی بارگیری را نمی‌گیرد.","img ist ein leeres Element ohne End-Tag.":"img یک عنصر خالی بدون تگ پایان است.","img zeigt ein Bild. src enthält die Bildquelle.":"img یک عکس نشان می‌دهد. src منبع عکس را در بر دارد.","alt beschreibt das Bild für Menschen, die es nicht sehen können.":"alt عکس را برای کسانی که نمی‌توانند آن را ببینند توصیف می‌کند.","Ein Bild braucht eine gültige Quelle und bei wichtigen Informationen einen Alternativtext.":"یک عکس به یک منبع معتبر و برای معلومات مهم به یک متن جایگزین نیاز دارد.","CSS Farben und Schrift":"رنگ‌ها و فونت با CSS","Du kannst Farben und Schriftarten mit CSS ändern.":"شما می‌توانید رنگ‌ها و فونت‌ها را با CSS تغییر دهید.","CSS trennt Inhalt und Aussehen":"CSS محتوا و ظاهر را جدا می‌کند","Du kannst einen Raum neu streichen, ohne die Möbel zu ersetzen. HTML bleibt der Inhalt deiner Seite. CSS bestimmt die Gestaltung. Eine Regel beginnt mit einem Selektor.":"می‌توانید یک اتاق را دوباره رنگ کنید، بدون اینکه فرنیچر را عوض کنید. HTML محتوای صفحهٔ شما می‌ماند. CSS طراحی را تعیین می‌کند. یک قاعده با یک انتخابگر شروع می‌شود.","h1 wählt die Überschrift. color setzt ihre Schriftfarbe. Die letzte Klammer schließt die Regel.":"h1 عنوان را انتخاب می‌کند. color رنگ متن آن را می‌گذارد. قوس آخر قاعده را می‌بندد.","Eine Hintergrundfarbe gestalten":"طراحی یک رنگ پس‌زمینه","Eine helle Wand kann dunklen Text gut lesbar machen. background-color setzt die Fläche hinter einem Element. Für die ganze Seite wählst du body. Achte auf genügend Kontrast.":"یک دیوار روشن می‌تواند متن تیره را خوب خوانا کند. background-color سطح پشت یک عنصر را می‌گذارد. برای تمام صفحه body را انتخاب می‌کنید. به کنتراست کافی توجه کنید.","body bezeichnet die gesamte Seite. background-color setzt ein helles Blau. Das Semikolon beendet die Eigenschaft.":"body تمام صفحه را مشخص می‌کند. background-color یک آبی روشن می‌گذارد. نقطه‌کامه ویژگی را تمام می‌کند.","Schriftarten auswählen":"انتخاب فونت‌ها","Eine gut lesbare Schrift ist wie eine klare Handschrift. font-family legt die Schriftfamilie fest. Du kannst eine Ersatzschrift angeben. Der Browser nimmt eine verfügbare Schrift.":"یک فونت خوب خوانا مثل یک خط دست روشن است. font-family خانوادهٔ فونت را تعیین می‌کند. می‌توانید یک فونت جایگزین بنویسید. براوزر یک فونت در دسترس را برمی‌دارد.","Arial wird zuerst versucht. sans-serif ist die Ersatzfamilie ohne Serifen. Die Regel gilt für den body.":"اول Arial امتحان می‌شود. sans-serif خانوادهٔ جایگزین بدون سریف است. این قاعده برای body است.","Verschiedene Elemente getrennt gestalten":"طراحی جداگانهٔ عنصرهای مختلف","Du musst nicht jeden Text gleich färben. Eine Überschrift darf kräftiger sein als ein Absatz. Schreibe dafür zwei CSS-Regeln. Der HTML-Inhalt bleibt dabei unverändert.":"لازم نیست هر متن را یک رنگ کنید. یک عنوان می‌تواند پررنگ‌تر از یک پاراگراف باشد. برای این کار دو قاعدهٔ CSS بنویسید. محتوای HTML در این میان بدون تغییر می‌ماند.","Die erste Regel färbt h1 dunkelgrün. Die zweite setzt die Absatzfarbe auf Dunkelgrau.":"قاعدهٔ اول h1 را سبز تیره می‌کند. قاعدهٔ دوم رنگ پاراگراف را خاکستری تیره می‌گذارد.","Doppelpunkt nach der Eigenschaft vergessen":"فراموش کردن دونقطه بعد از ویژگی","Schreibe color: blue; statt color blue;.":"به جای color blue; بنویسید color: blue;.","Schließende geschweifte Klammer fehlt":"قوس گُل‌دار بسته کم است","Prüfe, ob jede CSS-Regel mit } endet.":"بررسی کنید که آیا هر قاعدهٔ CSS با } تمام می‌شود.","Text und Hintergrund haben fast dieselbe Farbe":"متن و پس‌زمینه تقریباً یک رنگ دارند","Wähle gut unterscheidbare Farben für eine lesbare Seite.":"برای یک صفحهٔ خوانا رنگ‌هایی انتخاب کنید که خوب از هم جدا شوند.","Ändere die Hintergrundfarbe, Schrift und Überschriftfarbe.":"رنگ پس‌زمینه، فونت و رنگ عنوان را تغییر دهید.","Der Hintergrund hat eine Farbe.":"پس‌زمینه یک رنگ دارد.","Die Schriftart wurde eingestellt.":"فونت تنظیم شده است.","Die Überschrift hat eine Textfarbe.":"عنوان یک رنگ متن دارد.","Welche CSS-Eigenschaft färbt den Hintergrund?":"کدام ویژگی CSS پس‌زمینه را رنگ می‌کند؟","background-color verändert die Fläche.":"background-color سطح را تغییر می‌دهد.","color verändert die Schrift.":"color متن را تغییر می‌دهد.","font-family wählt eine Schriftart.":"font-family یک فونت انتخاب می‌کند.","Was bedeutet body { color: red; }?":"body { color: red; } یعنی چه؟","Der Text im body wird rot.":"متن در body سرخ می‌شود.","Die Seite bekommt einen roten Rand.":"صفحه یک حاشیهٔ سرخ می‌گیرد.","Alle Bilder werden gelöscht.":"همهٔ عکس‌ها پاک می‌شوند.","Die Regel setzt die Textfarbe.":"این قاعده رنگ متن را می‌گذارد.","Ein Rand braucht border.":"یک حاشیه به border نیاز دارد.","CSS entfernt keine Bilder aus HTML.":"CSS هیچ عکسی را از HTML پاک نمی‌کند.","Warum steht Arial, sans-serif in einer Regel?":"چرا Arial, sans-serif در یک قاعده نوشته می‌شود؟","Um zwei Farben zu mischen.":"برای مخلوط کردن دو رنگ.","Um einen Link zu erstellen.":"برای ساختن یک لینک.","Um eine Ersatzschrift zu haben.":"برای داشتن یک فونت جایگزین.","Wenn Arial fehlt, nutzt der Browser eine andere serifenlose Schrift.":"اگر Arial نباشد، براوزر یک فونت دیگر بدون سریف را به کار می‌برد.","Farben werden anders festgelegt.":"رنگ‌ها جور دیگری تعیین می‌شوند.","Ein Link entsteht in HTML.":"یک لینک در HTML ساخته می‌شود.","body wählt die ganze Seite. background-color setzt die Hintergrundfarbe.":"body تمام صفحه را انتخاب می‌کند. background-color رنگ پس‌زمینه را می‌گذارد.","color ändert die Textfarbe. font-family wählt eine Schrift.":"color رنگ متن را تغییر می‌دهد. font-family یک فونت انتخاب می‌کند.","CSS-Farbwerte und Schriftregeln verändern die Darstellung, nicht den HTML-Inhalt.":"مقدارهای رنگ و قاعده‌های فونت CSS نمایش را تغییر می‌دهند، نه محتوای HTML را.","CSS Abstände und Kästen":"فاصله‌ها و جعبه‌ها با CSS","Du kannst einen Bereich mit Abstand und Rand gestalten.":"شما می‌توانید یک بخش را با فاصله و حاشیه طراحی کنید.","Abstände schaffen Ordnung":"فاصله‌ها نظم ایجاد می‌کنند","Auf einer Visitenkarte steht Text nicht direkt am Rand. Auch Webseiten brauchen freie Flächen. CSS kann Abstände innen und außen setzen. So wirkt ein Bereich ruhiger.":"روی یک کارت ویزیت متن مستقیم کنار لبه نیست. ویب‌سایت‌ها هم به سطح‌های خالی نیاز دارند. CSS می‌تواند فاصله‌های داخلی و بیرونی بگذارد. به این ترتیب یک بخش آرام‌تر به نظر می‌رسد.","section wählt den Bereich. padding gibt dem Inhalt innen 16 Pixel Platz.":"section بخش را انتخاب می‌کند. padding به محتوا در داخل 16 پیکسل جا می‌دهد.","Padding liegt innerhalb des Kastens":"padding داخل جعبه است","Stell dir ein Paket mit Schutzpapier vor. Das Papier liegt zwischen Ware und Karton. Genau so liegt padding zwischen Inhalt und Rand. Größere Werte schaffen mehr Luft.":"یک بسته با کاغذ محافظ را تصور کنید. کاغذ بین جنس و کارتن است. padding هم دقیقاً بین محتوا و حاشیه است. مقدارهای بزرگ‌تر جای بیشتری ایجاد می‌کنند.","Der Punkt vor karte wählt die CSS-Klasse. padding gibt auf allen vier Seiten Innenabstand.":"نقطهٔ پیش از karte کلاس CSS را انتخاب می‌کند. padding در هر چهار طرف فاصلهٔ داخلی می‌دهد.","Margin trennt zwei Kästen":"margin دو جعبه را جدا می‌کند","Zwei Bilderrahmen brauchen Abstand voneinander. margin legt diesen äußeren Abstand fest. Er liegt außerhalb des Rahmens. Du kannst margin und padding gleichzeitig nutzen.":"دو قاب عکس به فاصله از هم نیاز دارند. margin این فاصلهٔ بیرونی را تعیین می‌کند. بیرون از قاب است. می‌توانید margin و padding را هم‌زمان به کار ببرید.","margin trennt die Karte von anderen Elementen. padding hält ihren Inhalt vom eigenen Rand fern.":"margin کارت را از عنصرهای دیگر جدا می‌کند. padding محتوای آن را از لبهٔ خودش دور نگه می‌دارد.","Rand und runde Ecken gestalten":"طراحی حاشیه و گوشه‌های گرد","Ein Rahmen macht einen Bereich erkennbar. border setzt Dicke, Art und Farbe. border-radius rundet die Ecken. Verwende beides sparsam, damit der Text wichtig bleibt.":"یک قاب یک بخش را قابل شناخت می‌کند. border ضخامت، نوع و رنگ را می‌گذارد. border-radius گوشه‌ها را گرد می‌کند. هر دو را کم به کار ببرید تا متن مهم بماند.","border zeichnet einen zwei Pixel dicken grünen Rand. border-radius rundet die vier Ecken.":"border یک حاشیهٔ سبز به ضخامت دو پیکسل رسم می‌کند. border-radius چهار گوشه را گرد می‌کند.","margin mit padding verwechselt":"اشتباه گرفتن margin با padding","Prüfe, ob du Platz außerhalb oder innerhalb des Rahmens brauchst.":"بررسی کنید که آیا جا را بیرون یا داخل قاب لازم دارید.","Einheit px fehlt":"واحد px کم است","Schreibe padding: 20px; statt padding: 20;.":"به جای padding: 20; بنویسید padding: 20px;.","border ohne Linienart":"border بدون نوع خط","Eine sichtbare Linie braucht etwa 2px solid green.":"یک خط قابل دید به چیزی مثل 2px solid green نیاز دارد.","Gestalte die Karte mit padding, border und border-radius.":"کارت را با padding، border و border-radius طراحی کنید.","Es gibt eine Karte.":"یک کارت وجود دارد.","Die Karte hat Innenabstand.":"کارت فاصلهٔ داخلی دارد.","Die Karte hat einen Rand.":"کارت یک حاشیه دارد.","Die Karte hat runde Ecken.":"کارت گوشه‌های گرد دارد.","Wo wirkt padding?":"padding کجا اثر می‌کند؟","Innerhalb des Kastens.":"داخل جعبه.","Zwischen zwei Browser-Tabs.":"بین دو تب براوزر.","Nur auf Bildern.":"فقط روی عکس‌ها.","padding schafft Platz zwischen Inhalt und Rand.":"padding بین محتوا و حاشیه جا ایجاد می‌کند.","Tabs haben damit nichts zu tun.":"تب‌ها به آن ربطی ندارند.","padding gilt für viele Elemente.":"padding برای بسیاری از عنصرها صدق می‌کند.","Welche Regel rundet die Ecken?":"کدام قاعده گوشه‌ها را گرد می‌کند؟","border-radius rundet den Rand.":"border-radius حاشیه را گرد می‌کند.","margin ist äußerer Abstand.":"margin فاصلهٔ بیرونی است.","color verändert Textfarbe.":"color رنگ متن را تغییر می‌دهد.","Was macht margin?":"margin چه کار می‌کند؟","Es färbt den Rahmen.":"قاب را رنگ می‌کند.","Es schafft Abstand außerhalb des Elements.":"بیرون از عنصر فاصله ایجاد می‌کند.","Es ändert den HTML-Text.":"متن HTML را تغییر می‌دهد.","margin ist der Außenabstand.":"margin فاصلهٔ بیرونی است.","Die Randfarbe kommt aus border.":"رنگ حاشیه از border می‌آید.","CSS verändert nicht den Textinhalt.":"CSS محتوای متن را تغییر نمی‌دهد.","padding ist der Abstand im Kasten. margin ist der Abstand außen.":"padding فاصلهٔ داخل جعبه است. margin فاصلهٔ بیرونی است.","border ist der Rand. border-radius macht die Ecken rund.":"border حاشیه است. border-radius گوشه‌ها را گرد می‌کند.","Innenabstand und Rahmen helfen dabei, zusammengehörige Informationen zu erkennen.":"فاصلهٔ داخلی و قاب کمک می‌کنند معلومات مربوط به هم شناخته شوند.","Erstes JavaScript (Knopf)":"اولین JavaScript (دکمه)","Du kannst auf einen Klick reagieren.":"شما می‌توانید به یک کلیک واکنش نشان دهید.","Ein Knopf kann eine Aktion starten":"یک دکمه می‌تواند یک کار را شروع کند","Ein Lichtschalter wartet darauf, dass du ihn drückst. Ein HTML-Knopf funktioniert ähnlich. Zuerst legst du das Element an. Mit einer id kannst du es später eindeutig finden.":"یک سویچ چراغ منتظر است که آن را فشار دهید. یک دکمهٔ HTML هم شبیه آن کار می‌کند. اول عنصر را می‌سازید. با یک id می‌توانید آن را بعداً به‌طور یکتا پیدا کنید.","button erzeugt den Knopf. id gibt ihm den Namen licht. Der Text steht auf der Schaltfläche.":"button دکمه را می‌سازد. id به آن نام licht را می‌دهد. متن روی دکمه نوشته می‌شود.","JavaScript findet den Knopf":"JavaScript دکمه را پیدا می‌کند","Bevor du eine Lampe einschaltest, musst du den richtigen Schalter finden. querySelector sucht ein Element im Dokument. Das Zeichen # bedeutet: Suche nach einer id. Das Ergebnis kannst du für Aktionen verwenden.":"پیش از روشن کردن یک چراغ باید سویچ درست را پیدا کنید. querySelector یک عنصر را در سند جستجو می‌کند. نشانهٔ # یعنی: دنبال یک id بگرد. نتیجه را می‌توانید برای کارها به کار ببرید.","const legt eine Variable an. querySelector sucht das Element mit der id licht. Der Knopf wird in knopf gespeichert.":"const یک متغیر می‌سازد. querySelector عنصری را که id آن licht است جستجو می‌کند. دکمه در knopf نگه داشته می‌شود.","Auf einen Klick hören":"گوش دادن به یک کلیک","Ein Ereignis heißt auf Englisch event. addEventListener wartet auf ein bestimmtes Ereignis. Hier ist es click. Die Funktion zwischen den Klammern läuft erst nach dem Drücken.":"به یک رویداد به انگلیسی event می‌گویند. addEventListener منتظر یک رویداد معین می‌ماند. اینجا آن click است. تابع داخل قوس‌ها فقط بعد از فشار دادن اجرا می‌شود.","Die erste Zeile meldet den Klick an. Die zweite gibt eine Nachricht aus. Die letzte Zeile schließt die Funktion.":"خط اول کلیک را ثبت می‌کند. خط دوم یک پیام نشان می‌دهد. خط آخر تابع را می‌بندد.","Text nach dem Klick ändern":"تغییر متن بعد از کلیک","Ein Knopf soll ein sichtbares Ergebnis haben. Dafür kannst du einen Absatz ändern. textContent ersetzt den Text eines Elements. Prüfe, ob die id im HTML genau passt.":"یک دکمه باید یک نتیجهٔ قابل دید داشته باشد. برای این کار می‌توانید یک پاراگراف را تغییر دهید. textContent متن یک عنصر را عوض می‌کند. بررسی کنید که آیا id در HTML دقیقاً جور می‌آید.","querySelector findet den Absatz mit der id meldung. textContent schreibt Fertig hinein.":"querySelector پاراگرافی را که id آن meldung است پیدا می‌کند. textContent کلمهٔ Fertig را در آن می‌نویسد.","id im JavaScript falsch geschrieben":"id در JavaScript اشتباه نوشته شد","Vergleiche #aktion mit id=\"aktion\" im HTML.":"‎#aktion را با id=\"aktion\" در HTML مقایسه کنید.","click ohne Anführungszeichen":"click بدون علامهٔ نقل‌قول","Der Ereignisname muss als Text angegeben werden: 'click'.":"نام رویداد باید به شکل متن نوشته شود: 'click'.","Klammer bei addEventListener vergessen":"فراموش کردن قوس در addEventListener","Kontrolliere die öffnenden und schließenden runden sowie geschweiften Klammern.":"قوس‌های گرد و گُل‌دار باز و بسته را بررسی کنید.","Lass den Knopf den Text unter ihm verändern.":"کاری کنید که دکمه متن زیر خود را تغییر دهد.","Es gibt einen Knopf.":"یک دکمه وجود دارد.","JavaScript hört auf Klicks.":"JavaScript به کلیک‌ها گوش می‌دهد.","JavaScript ändert Text.":"JavaScript متن را تغییر می‌دهد.","Was bewirkt addEventListener('click', ...)?":"addEventListener('click', ...) چه کار می‌کند؟","Es färbt alle Überschriften.":"همهٔ عنوان‌ها را رنگ می‌کند.","Es speichert ein Bild.":"یک عکس ذخیره می‌کند.","Es reagiert auf einen Klick.":"به یک کلیک واکنش نشان می‌دهد.","Ein Klick löst die Funktion aus.":"یک کلیک تابع را اجرا می‌کند.","Bilder werden dadurch nicht gespeichert.":"با این کار عکس‌ها ذخیره نمی‌شوند.","Was sucht querySelector('#aktion')?":"querySelector('#aktion') چه چیزی را جستجو می‌کند؟","Ein Element mit der id aktion.":"عنصری با id برابر aktion.","Ein Element mit dem Tag aktion.":"عنصری با تگ aktion.","Alle Elemente der Seite.":"همهٔ عنصرهای صفحه.","Das # kennzeichnet eine id.":"‎# یک id را مشخص می‌کند.","Ein Tag-Selektor hat kein #.":"یک انتخابگر تگ # ندارد.","querySelector gibt nur den ersten Treffer zurück.":"querySelector فقط اولین مورد پیدا شده را پس می‌دهد.","Welche Eigenschaft verändert den sichtbaren Text?":"کدام ویژگی متن قابل دید را تغییر می‌دهد؟","textContent setzt den Textinhalt.":"textContent محتوای متن را می‌گذارد.","background-color ist eine CSS-Eigenschaft.":"background-color یک ویژگی CSS است.","href enthält eine Linkadresse.":"href یک آدرس لینک را در بر دارد.","JavaScript wartet auf Ereignisse. Ein Klick ist ein Ereignis.":"JavaScript منتظر رویدادها می‌ماند. یک کلیک یک رویداد است.","addEventListener verbindet den Klick mit einer Aktion. textContent verändert Text.":"addEventListener کلیک را با یک کار وصل می‌کند. textContent متن را تغییر می‌دهد.","Ein Klick-Ereignis verbindet einen Knopf mit einer JavaScript-Reaktion.":"یک رویداد کلیک یک دکمه را با یک واکنش JavaScript وصل می‌کند.","Variablen und Rechnen":"متغیرها و حساب کردن","Du kannst einen Preis mit einer Menge multiplizieren.":"شما می‌توانید یک قیمت را در یک تعداد ضرب کنید.","Variablen speichern Werte":"متغیرها مقدارها را نگه می‌دارند","An der Kasse merkst du dir den Preis eines Produkts. Eine Variable speichert so einen Wert im Programm. Ein Name wie preis ist leichter zu verstehen als x. Mit const legst du einen Wert an, den du nicht neu zuweisen möchtest.":"در صندوق قیمت یک جنس را به یاد می‌سپارید. یک متغیر چنین مقداری را در برنامه نگه می‌دارد. یک نام مثل preis از x آسان‌تر فهمیده می‌شود. با const مقداری می‌سازید که نمی‌خواهید دوباره به آن مقدار بدهید.","const erstellt die Variable. preis ist ihr Name. Die Zahl 4 ist der gespeicherte Wert.":"const متغیر را می‌سازد. preis نام آن است. عدد 4 مقدار ذخیره‌شده است.","let erlaubt eine spätere Änderung":"let تغییر بعدی را اجازه می‌دهد","Beim Einkaufen kann die Menge noch wachsen. Dafür eignet sich let. Eine let-Variable darf später einen anderen Wert bekommen. Eine const-Variable darf nicht neu zugewiesen werden.":"هنگام خرید ممکن است تعداد هنوز بیشتر شود. برای این کار let مناسب است. یک متغیر let بعداً می‌تواند مقدار دیگری بگیرد. به یک متغیر const نمی‌شود دوباره مقدار داد.","Zeile 1 startet mit zwei Artikeln. Zeile 2 ändert die Menge auf drei. Das ist mit let erlaubt.":"خط 1 با دو جنس شروع می‌کند. خط 2 تعداد را به سه تغییر می‌دهد. این کار با let مجاز است.","Zahlen und Texte sind verschieden":"عددها و متن‌ها فرق دارند","Eine Zahl kannst du direkt multiplizieren. Text steht in Anführungszeichen und heißt String. Die Zeichenfolge '4' sieht wie eine Zahl aus, ist aber Text. Bei plus ist dieser Unterschied besonders wichtig.":"یک عدد را می‌توانید مستقیم ضرب کنید. متن داخل علامهٔ نقل‌قول است و String نام دارد. رشتهٔ '4' مثل یک عدد به نظر می‌رسد، اما متن است. در علامهٔ جمع این فرق به‌خصوص مهم است.","Zeile 1 speichert eine Zahl. Zeile 2 speichert Text. Die dritte Zeile rechnet mit der Zahl und ergibt 6.":"خط 1 یک عدد نگه می‌دارد. خط 2 متن نگه می‌دارد. خط سوم با عدد حساب می‌کند و نتیجهٔ 6 می‌دهد.","Preis mal Menge rechnen":"حساب قیمت ضرب تعداد","Eine Rechnung an der Kasse nutzt Preis und Stückzahl. In JavaScript steht * für Multiplikation. Das Zeichen + kann Zahlen addieren oder Texte verbinden. Zeige das Ergebnis mit einer passenden Einheit.":"یک حساب در صندوق از قیمت و تعداد استفاده می‌کند. در JavaScript ‏* برای ضرب است. نشانهٔ + می‌تواند عددها را جمع کند یا متن‌ها را وصل کند. نتیجه را با یک واحد مناسب نشان دهید.","Zeile 1 multipliziert Preis und Menge. Zeile 2 verbindet das Ergebnis mit dem Text Euro. So entsteht eine lesbare Ausgabe.":"خط 1 قیمت و تعداد را ضرب می‌کند. خط 2 نتیجه را با متن Euro وصل می‌کند. به این ترتیب یک خروجی خوانا ساخته می‌شود.","const später neu zugewiesen":"const بعداً دوباره مقدار گرفت","Wenn sich die Menge ändern soll, verwende let statt const.":"اگر تعداد باید تغییر کند، به جای const از let استفاده کنید.","Zahlen als Text gespeichert":"عددها به شکل متن ذخیره شدند","Bei '4' + '2' entsteht '42' statt 6; rechne mit echten Zahlen.":"در '4' + '2' به جای 6 نتیجهٔ '42' ساخته می‌شود؛ با عددهای واقعی حساب کنید.","Plus statt Stern für den Gesamtpreis":"علامهٔ جمع به جای ستاره برای قیمت مجموعی","Für Preis mal Menge brauchst du *, nicht +.":"برای قیمت ضرب تعداد به * نیاز دارید، نه +.","Berechne den Gesamtpreis für drei Artikel zu je vier Euro.":"قیمت مجموعی سه جنس را که هر کدام چهار یورو است حساب کنید.","Es gibt eine Variable.":"یک متغیر وجود دارد.","Der Preis wird multipliziert.":"قیمت ضرب می‌شود.","Das Ergebnis wird angezeigt.":"نتیجه نشان داده می‌شود.","Welche Variable darf neu zugewiesen werden?":"به کدام متغیر می‌شود دوباره مقدار داد؟","Beide niemals":"هیچ کدام هرگز","let erlaubt spätere Änderungen.":"let تغییرهای بعدی را اجازه می‌دهد.","const verhindert eine neue Zuweisung.":"const از مقدار دادن دوباره جلوگیری می‌کند.","let kann neu zugewiesen werden.":"به let می‌شود دوباره مقدار داد.","Was ergibt 3 * 4?":"3 * 4 چه نتیجه‌ای می‌دهد؟","Der Stern multipliziert beide Zahlen.":"ستاره هر دو عدد را ضرب می‌کند.","34 könnte bei Text-Verkettung entstehen.":"34 ممکن است با چسپاندن متن ساخته شود.","7 wäre das Ergebnis einer Addition.":"7 نتیجهٔ یک جمع می‌بود.","Was ergibt '4' + '2' in JavaScript?":"'4' + '2' در JavaScript چه نتیجه‌ای می‌دهد؟","Plus verbindet hier zwei Texte.":"علامهٔ جمع اینجا دو متن را وصل می‌کند.","Beide Werte sind Strings, keine Zahlen.":"هر دو مقدار String هستند، نه عدد.","Es findet keine Multiplikation statt.":"هیچ ضربی انجام نمی‌شود.","const erstellt eine Variable. Der Wert bleibt für diese Variable fest.":"const یک متغیر می‌سازد. مقدار برای این متغیر ثابت می‌ماند.","Das Zeichen * bedeutet mal. Mit textContent zeigst du das Ergebnis.":"نشانهٔ * یعنی ضرب. با textContent نتیجه را نشان می‌دهید.","Zahlen lassen sich multiplizieren; das Pluszeichen verbindet bei Texten Zeichenketten.":"عددها را می‌شود ضرب کرد؛ علامهٔ جمع در متن‌ها رشته‌ها را به هم وصل می‌کند.","Eingaben auswerten (if/else)":"ارزیابی ورودی‌ها (if/else)","Du kannst eine Eingabe prüfen und unterschiedlich antworten.":"شما می‌توانید یک ورودی را بررسی کنید و جواب‌های مختلف بدهید.","Ein Eingabefeld nimmt Daten an":"یک خانهٔ ورودی داده می‌گیرد","Bei einem Formular schreibst du deinen Namen in ein Feld. HTML stellt dafür input bereit. Mit einem label erklärst du den Zweck. Die id verbindet das Feld mit JavaScript.":"در یک فورم نام خود را در یک خانه می‌نویسید. HTML برای این کار input را فراهم می‌کند. با یک label هدف را توضیح می‌دهید. id خانه را با JavaScript وصل می‌کند.","label beschreibt das Feld. for zeigt auf die id name. input nimmt die Eingabe an.":"label خانه را توصیف می‌کند. for به id ‏name اشاره می‌کند. input ورودی را می‌گیرد.","Den aktuellen Text auslesen":"خواندن متن فعلی","Ein leeres Formular enthält noch keine Antwort. JavaScript kann den aktuellen Wert lesen. Die Eigenschaft value liefert bei einem Textfeld einen String. Mit trim entfernst du Leerzeichen am Anfang und Ende.":"یک فورم خالی هنوز جوابی ندارد. JavaScript می‌تواند مقدار فعلی را بخواند. ویژگی value در یک خانهٔ متنی یک String می‌دهد. با trim فاصله‌های آغاز و پایان را پاک می‌کنید.","querySelector findet das Feld. value liest seinen Text. trim entfernt unnötige Rand-Leerzeichen.":"querySelector خانه را پیدا می‌کند. value متن آن را می‌خواند. trim فاصله‌های غیرضروری دو طرف را پاک می‌کند.","if prüft eine Bedingung":"if یک شرط را بررسی می‌کند","An einer Tür entscheidest du: Ist sie offen oder geschlossen? if stellt eine ähnliche Frage. Mit === vergleichst du zwei Werte genau. Die Anweisungen im Block laufen nur, wenn die Bedingung stimmt.":"در یک دروازه تصمیم می‌گیرید: باز است یا بسته؟ if سوال مشابهی می‌پرسد. با === دو مقدار را دقیق مقایسه می‌کنید. دستورهای داخل بلاک فقط وقتی اجرا می‌شوند که شرط درست باشد.","if prüft, ob der Name leer ist. Die zweite Zeile gibt dann einen Hinweis aus. Die Klammer beendet den Block.":"if بررسی می‌کند که آیا نام خالی است. خط دوم در آن صورت یک پیام نشان می‌دهد. قوس بلاک را تمام می‌کند.","else behandelt den anderen Fall":"else حالت دیگر را رسیدگی می‌کند","Ein Formular braucht auch eine Antwort, wenn etwas eingegeben wurde. else läuft, wenn die if-Bedingung falsch ist. So kannst du leere und ausgefüllte Felder unterschiedlich behandeln. Zeige die Nachricht direkt unter dem Formular.":"یک فورم وقتی چیزی وارد شده هم به یک جواب نیاز دارد. else وقتی اجرا می‌شود که شرط if نادرست باشد. به این ترتیب می‌توانید خانه‌های خالی و پرشده را جور دیگری رسیدگی کنید. پیام را مستقیم زیر فورم نشان دهید.","Der erste Block meldet eine leere Eingabe. else begrüßt eine Person mit Namen. Das Plus verbindet hier Texte.":"بلاک اول یک ورودی خالی را گزارش می‌دهد. else به یک شخص با نامش خوش‌آمد می‌گوید. علامهٔ جمع اینجا متن‌ها را وصل می‌کند.","= statt === im Vergleich":"= به جای === در مقایسه","Ein einzelnes = weist einen Wert zu; === prüft, ob zwei Werte gleich sind.":"یک = تنها یک مقدار می‌دهد؛ === بررسی می‌کند که آیا دو مقدار برابرند.","value am falschen Element gelesen":"value از عنصر اشتباه خوانده شد","Lies die Eingabe vom input und nicht vom Absatz für die Ausgabe.":"ورودی را از input بخوانید، نه از پاراگراف خروجی.","else ohne passenden if-Block":"else بدون بلاک if مربوط","else gehört direkt zu einer vorherigen if-Bedingung.":"else مستقیم به یک شرط if پیش از خود تعلق دارد.","Prüfe die Eingabe: Bei leerem Namen zeige einen Hinweis, sonst eine Begrüßung.":"ورودی را بررسی کنید: با نام خالی یک پیام نشان دهید، در غیر آن یک خوش‌آمد.","Es gibt ein Eingabefeld.":"یک خانهٔ ورودی وجود دارد.","JavaScript liest die Eingabe.":"JavaScript ورودی را می‌خواند.","Es gibt eine if-Bedingung.":"یک شرط if وجود دارد.","Es gibt einen else-Fall.":"یک حالت else وجود دارد.","Was prüft name === ''?":"name === '' چه چیزی را بررسی می‌کند؟","Ob der Name eine Zahl ist.":"اینکه آیا نام یک عدد است.","Ob das Feld blau ist.":"اینکه آیا خانه آبی است.","Ob der Text leer ist.":"اینکه آیا متن خالی است.","Zwei einfache Anführungszeichen stehen für leeren Text.":"دو علامهٔ نقل‌قول ساده به معنای متن خالی است.","Die Bedingung prüft keine Zahl.":"این شرط عددی را بررسی نمی‌کند.","CSS legt Farben fest.":"CSS رنگ‌ها را تعیین می‌کند.","Wann läuft else?":"else چه وقت اجرا می‌شود؟","Wenn if falsch ist.":"وقتی if نادرست باشد.","Immer vor if.":"همیشه پیش از if.","Nur wenn CSS geladen wurde.":"فقط وقتی CSS بارگیری شده باشد.","else ist der alternative Zweig.":"else شاخهٔ جایگزین است.","else folgt auf if.":"else بعد از if می‌آید.","Die Bedingung hängt nicht von CSS ab.":"شرط به CSS بستگی ندارد.","Was macht .value bei einem Textfeld?":".value در یک خانهٔ متنی چه کار می‌کند؟","Es löscht das Feld.":"خانه را پاک می‌کند.","Es liefert den eingegebenen Text.":"متن واردشده را می‌دهد.","Es erzeugt eine neue Überschrift.":"یک عنوان تازه می‌سازد.","Der aktuelle Feldinhalt wird als Text gelesen.":"محتوای فعلی خانه به شکل متن خوانده می‌شود.","value liest oder setzt einen Wert, löscht ihn aber nicht automatisch.":"value یک مقدار را می‌خواند یا می‌گذارد، اما آن را خودکار پاک نمی‌کند.","Überschriften entstehen in HTML.":"عنوان‌ها در HTML ساخته می‌شوند.","input ist ein Eingabefeld. value liest den eingegebenen Text.":"input یک خانهٔ ورودی است. value متن واردشده را می‌خواند.","if prüft eine Bedingung. else ist der andere Fall.":"if یک شرط را بررسی می‌کند. else حالت دیگر است.","Ein Vergleich mit === prüft Gleichheit, ohne einer Variablen einen Wert zuzuweisen.":"یک مقایسه با === برابری را بررسی می‌کند، بدون اینکه به یک متغیر مقدار بدهد.","Abschlussprojekt Visitenkarten-Webseite":"پروژهٔ پایانی: ویب‌سایت کارت ویزیت","Du kannst eine eigene Visitenkarten-Webseite erstellen.":"شما می‌توانید یک ویب‌سایت کارت ویزیت خودتان بسازید.","Plane deine digitale Visitenkarte":"کارت ویزیت دیجیتالی خود را برنامه‌ریزی کنید","Eine gedruckte Visitenkarte zeigt Name und Beruf auf wenig Platz. Deine Webseite braucht ebenfalls einen klaren Aufbau. Schreibe zuerst auf, welche Informationen Besucher finden sollen. Ein Name, ein kurzer Satz und eine Kontaktaktion reichen für den Anfang.":"یک کارت ویزیت چاپی نام و شغل را در جای کم نشان می‌دهد. ویب‌سایت شما هم به یک ساختار روشن نیاز دارد. اول بنویسید که بازدیدکنندگان چه معلوماتی را باید پیدا کنند. یک نام، یک جملهٔ کوتاه و یک راه تماس برای شروع کافی است.","section gruppiert die Karte. class gibt ihr einen CSS-Namen. h1 zeigt die Person.":"section کارت را گروه‌بندی می‌کند. class به آن یک نام CSS می‌دهد. h1 شخص را نشان می‌دهد.","Baue den Inhalt mit HTML":"محتوا را با HTML بسازید","Besucher sollen sofort verstehen, wer du bist. Eine Überschrift zeigt deinen Namen. Ein Absatz erklärt dein Angebot. Ein Knopf bietet eine nächste Aktion.":"بازدیدکنندگان باید فوراً بفهمند شما کیستید. یک عنوان نام شما را نشان می‌دهد. یک پاراگراف خدمت شما را توضیح می‌دهد. یک دکمه کار بعدی را پیشنهاد می‌کند.","Zeile 1 zeigt den Namen. Zeile 2 beschreibt die Tätigkeit. Zeile 3 erstellt den Kontaktknopf.":"خط 1 نام را نشان می‌دهد. خط 2 فعالیت را توصیف می‌کند. خط 3 دکمهٔ تماس را می‌سازد.","Gestalte die Karte mit CSS":"کارت را با CSS طراحی کنید","Eine Karte wirkt professionell, wenn Text und Hintergrund gut zusammenpassen. Wähle eine ruhige Farbe. Mit padding schaffst du Innenabstand. Abgerundete Ecken geben dem Kasten eine weiche Form.":"یک کارت وقتی حرفه‌ای به نظر می‌رسد که متن و پس‌زمینه خوب با هم جور شوند. یک رنگ آرام انتخاب کنید. با padding فاصلهٔ داخلی ایجاد می‌کنید. گوشه‌های گرد به جعبه شکل نرمی می‌دهند.","background-color färbt die Fläche. padding schafft Platz zum Rand. border-radius rundet die Ecken.":"background-color سطح را رنگ می‌کند. padding تا لبه جا ایجاد می‌کند. border-radius گوشه‌ها را گرد می‌کند.","Verbinde den Knopf mit JavaScript":"دکمه را با JavaScript وصل کنید","Der Kontaktknopf soll nicht ohne Wirkung bleiben. Füge einen Absatz für die Antwort hinzu. JavaScript reagiert auf den Klick und zeigt eine Nachricht. Prüfe die Seite anschließend mit Maus und Finger.":"دکمهٔ تماس نباید بی‌اثر بماند. یک پاراگراف برای جواب اضافه کنید. JavaScript به کلیک واکنش نشان می‌دهد و یک پیام نشان می‌دهد. بعد از آن صفحه را با موس و انگشت بررسی کنید.","Die erste Zeile wartet auf den Klick. Die zweite setzt die Nachricht. Die letzte Zeile beendet die Aktion.":"خط اول منتظر کلیک است. خط دوم پیام را می‌گذارد. خط آخر کار را تمام می‌کند.","CSS-Klasse und HTML-Klasse passen nicht":"کلاس CSS و کلاس HTML جور نیستند","Vergleiche class=\"karte\" mit dem Selektor .karte.":"class=\"karte\" را با انتخابگر ‎.karte مقایسه کنید.","Kontaktknopf ohne Rückmeldung":"دکمهٔ تماس بدون پاسخ","Füge einen Absatz mit id=\"meldung\" hinzu und ändere seinen Text beim Klick.":"یک پاراگراف با id=\"meldung\" اضافه کنید و متن آن را هنگام کلیک تغییر دهید.","Karte auf schmalen Bildschirmen zu breit":"کارت در صفحه‌های باریک خیلی پهن است","Vermeide feste große Breiten und prüfe die Vorschau am Handy.":"از پهناهای بزرگ ثابت پرهیز کنید و پیش‌نمایش را در موبایل بررسی کنید.","Baue eine Visitenkarte mit Namen, Kontakttext, Farbe, Abständen und einem Knopf.":"یک کارت ویزیت با نام، متن تماس، رنگ، فاصله‌ها و یک دکمه بسازید.","Die Visitenkarte hat einen eigenen Namen.":"کارت ویزیت یک نام خودش را دارد.","Welche Datei enthält den Inhalt der Visitenkarte?":"کدام فایل محتوای کارت ویزیت را در بر دارد؟","HTML enthält Name, Absatz und Knopf.":"HTML نام، پاراگراف و دکمه را در بر دارد.","CSS gestaltet die Karte.":"CSS کارت را طراحی می‌کند.","JavaScript steuert den Klick.":"JavaScript کلیک را کنترول می‌کند.","Was bewirkt padding in .karte?":"padding در ‎.karte چه کار می‌کند؟","Abstand zwischen Inhalt und Rand.":"فاصله بین محتوا و لبه.","Eine neue Browserseite.":"یک صفحهٔ تازهٔ براوزر.","Das Löschen eines Absatzes.":"پاک کردن یک پاراگراف.","padding schafft Innenabstand.":"padding فاصلهٔ داخلی ایجاد می‌کند.","Navigation braucht einen Link oder ein Skript.":"رفتن به صفحهٔ دیگر به یک لینک یا اسکریپت نیاز دارد.","CSS entfernt keinen HTML-Absatz.":"CSS هیچ پاراگراف HTML را پاک نمی‌کند.","Welche Verbindung lässt den Kontaktknopf reagieren?":"کدام پیوند باعث می‌شود دکمهٔ تماس واکنش نشان دهد؟","href und alt":"href و alt","font-family und color":"font-family و color","id und addEventListener":"id و addEventListener","Die id findet den Knopf, der Listener reagiert auf Klicks.":"id دکمه را پیدا می‌کند و Listener به کلیک‌ها واکنش نشان می‌دهد.","href und alt gehören zu anderen Aufgaben.":"href و alt کارهای دیگری دارند.","Diese CSS-Eigenschaften gestalten nur.":"این ویژگی‌های CSS فقط طراحی می‌کنند.","HTML gibt der Karte Inhalt. CSS macht sie schön und gut lesbar.":"HTML به کارت محتوا می‌دهد. CSS آن را زیبا و خوب خوانا می‌کند.","JavaScript kann einen Knopf bedienen. Teste alles auch am Handy.":"JavaScript می‌تواند یک دکمه را به کار بیندازد. همه چیز را در موبایل هم آزمایش کنید.","Eine Visitenkarten-Seite soll Namen, Beschreibung und Kontakt verständlich zeigen.":"یک صفحهٔ کارت ویزیت باید نام، توضیح و تماس را قابل فهم نشان دهد."};})(typeof window!=="undefined"?window:globalThis);
